SELECT  FROM oj_solution
WHERE problem_id = #{problemId}
  AND status = 'PUBLISHED'
  AND audit_status != 'blocked'
ORDER BY is_featured DESC, like_count DESC, created_at DESC
LIMIT #{offset}, #{limit}

SELECT FROM oj_solution
AND (title LIKE CONCAT('%', #{keyword}, '%') OR problem_title LIKE CONCAT('%', #{keyword}, '%') OR username LIKE CONCAT('%', #{keyword}, '%'))
AND audit_status = #{auditStatus}
AND status != 'DELETED'
ORDER BY created_at DESC LIMIT #{offset}, #{limit}
